CREATE OR REPLACE FUNCTION public.sync_lease_payments() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_company companies%ROWTYPE; v_contract lease_contracts%ROWTYPE; v_aircraft fleet_aircraft%ROWTYPE; v_due integer; v_balance numeric; BEGIN SELECT * INTO v_company FROM companies WHERE user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RETURN; END IF; v_balance:=company_balance(v_company.id); FOR v_contract IN SELECT * FROM lease_contracts WHERE company_id=v_company.id ORDER BY starts_at,id FOR UPDATE LOOP SELECT * INTO v_aircraft FROM fleet_aircraft WHERE id=v_contract.aircraft_id; v_due:=least(v_contract.term_weeks,greatest(1,floor(extract(epoch FROM now()-v_contract.starts_at)/604800)::integer+1)); WHILE v_contract.paid_weeks<v_due LOOP v_contract.paid_weeks:=v_contract.paid_weeks+1; v_balance:=v_balance-v_contract.weekly_rate; INSERT INTO company_ledger(company_id,entry_type,debit_account,credit_account,amount,company_delta,balance_after,description,reference,idempotency_key) VALUES(v_company.id,'LEASE_PAYMENT','LESSOR_REVENUE','COMPANY_CASH',v_contract.weekly_rate,-v_contract.weekly_rate,v_balance,'Weekly lease payment – '||v_aircraft.registration,v_aircraft.registration,'contract:'||v_contract.id||':week:'||v_contract.paid_weeks); END LOOP; UPDATE lease_contracts SET paid_weeks=v_contract.paid_weeks WHERE id=v_contract.id; END LOOP; UPDATE fleet_aircraft fa SET next_payment_due=(SELECT least(lc.ends_at,lc.starts_at+make_interval(days=>lc.paid_weeks*7)) FROM lease_contracts lc WHERE lc.aircraft_id=fa.id ORDER BY lc.starts_at DESC LIMIT 1) WHERE fa.company_id=v_company.id AND fa.returned_at IS NULL; END $$;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.sign_lease(text,integer)'::regprocedure) INTO d; d:=replace(d,'IF p_weeks NOT BETWEEN 1 AND 52','IF p_weeks IS NULL OR p_weeks NOT BETWEEN 1 AND 52'); EXECUTE d; SELECT pg_get_functiondef('public.manage_lease(uuid,text,integer)'::regprocedure) INTO d; d:=replace(d,'IF p_weeks NOT BETWEEN 1 AND 52','IF p_weeks IS NULL OR p_weeks NOT BETWEEN 1 AND 52'); EXECUTE d; END $$;